function twoSum(nums, target) {
  const map = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) {
      return [map.get(complement), i];
    }
    map.set(nums[i], i);
  }
  return [];
}

function isValid(s) {
  const stack = [];
  const pairs = { ')': '(', '}': '{', ']': '[' };
  for (const ch of s) {
    if (ch === '(' || ch === '{' || ch === '[') {
      stack.push(ch);
    } else {
      if (stack.pop() !== pairs[ch]) return false;
    }
  }
  return stack.length === 0;
}

function maxSubArray(nums) {
  let maxSoFar = nums[0];
  let currentMax = nums[0];
  for (let i = 1; i < nums.length; i++) {
    currentMax = Math.max(nums[i], currentMax + nums[i]);
    maxSoFar = Math.max(maxSoFar, currentMax);
  }
  return maxSoFar;
}

function reverseList(arr) {
  // In our sandbox, linked lists are passed/returned as ordered arrays of values
  const result = [];
  for (let i = arr.length - 1; i >= 0; i--) {
    result.push(arr[i]);
  }
  return result;
}

function search(nums, target) {
  let left = 0;
  let right = nums.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1;
}

function minStackDriver(ops, args) {
  const stack = [];
  const minStack = [];
  const output = [];

  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    if (op === 'push') {
      const val = args[i][0];
      stack.push(val);
      if (minStack.length === 0 || val <= minStack[minStack.length - 1]) {
        minStack.push(val);
      }
      output.push(null);
    } else if (op === 'pop') {
      const val = stack.pop();
      if (val === minStack[minStack.length - 1]) {
        minStack.pop();
      }
      output.push(null);
    } else if (op === 'top') {
      output.push(stack[stack.length - 1]);
    } else if (op === 'getMin') {
      output.push(minStack[minStack.length - 1]);
    }
  }
  return output;
}
